"""
satir_farki(a, b) -> a'yı b'ye çeviren minimal diff dizisi.

Dönüş tipi: list[tuple[str, str]]
"""
from difflib import SequenceMatcher


def satir_farki(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    """a listesini b'ye çeviren minimal diff dizisi döndürür.

    Her eleman (" ", satir) ortak, ("-", satir) silinen, ("+", satir) eklenen.
    "-" ve " " a'yı, "+" ve " " b'yi sırayla verir.
    "+" ardından "-" asla gelmez.
    """
    sm = SequenceMatcher(lambda x: None, a, b)
    # - : silinen, ' ': ortak, + : eklenecek
    dels: list[str] = []
    keeps: list[str] = []
    adds: list[str] = []

    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "equal":
            for k in range(i1, i2):
                keeps.append(a[k])
        elif tag == "delete":
            for k in range(i1, i2):
                dels.append(a[k])
        elif tag == "insert":
            for k in range(j1, j2):
                adds.append(b[k])
        elif tag == "replace":
            for k in range(i1, i2):
                dels.append(a[k])
            for k in range(j1, j2):
                adds.append(b[k])

    result: list[tuple[str, str]] = []
    for row in dels:
        result.append(("-", row))
    for row in keeps:
        result.append((" ", row))
    for row in adds:
        result.append(("+", row))

    return result

