from difflib import SequenceMatcher


def satir_farki(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    """a satir listesini b'ye ceviren minimal diff dizisi.

    Elemanlar: (" ", satir), (" -", satir), ("+", satir).
    """
    sm = SequenceMatcher(None, a, b)
    blocks = sm.get_matching_blocks()
    ops = sm.get_opcodes()

    diff: list[tuple[str, str, int | None, int | None]] = []

    for tag, i1, i2, j1, j2 in ops:
        if tag == "equal":
            for k in range(i1, i2):
                diff.append((" ", a[k], k, k))
        elif tag == "delete":
            for k in range(i1, i2):
                diff.append(("-", a[k], k, None))
        elif tag == "insert":
            for k in range(j1, j2):
                diff.append(("+", b[k], None, k))
        elif tag == "replace":
            for k in range(i1, i2):
                diff.append(("-", a[k], k, None))
            for k in range(j1, j2):
                diff.append(("+", b[k], None, k))

    # Sıralama: "-" (a_idx var), " " (a_idx, b_idx var), "+" (b_idx var)
    # a_idx None olmayanlar önce, sonra None olanlar.
    # Aynı a_idx içinde: "-" < " " (zaten a_idx aynı, ama "-" önce)
    # a_idx farklıysa a_idx'ye göre, sonra b_idx'ye göre.
    diff.sort(key=lambda d: (d[2] if d[2] is not None else -1,
                             0 if d[0] == "-" else 1 if d[0] == " " else 2,
                             d[3] if d[3] is not None else -1))

    return [(tag, text) for tag, text, _, _ in diff]

